contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }
    function test(uint256 to) public {
        c.buyShares(to);
        bool isOne = c.RState() == 1;
        if (isOne) {
            assert(c.BASE_TARGET() == c.BASE_RESERVE());
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        c.buyShares(address(0x1));
        (,,,uint256 B0,uint256 Q0,) = c.getPMMStateForCall();
        uint256 i = c._I_();
        assert(B0 == DecimalMath.divFloor(Q0, i));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 i) public payable {
        require(true);
        c.buyShares(address(0));
        c.correctRState();
        assert(c._BASE_TARGET_() == c._BASE_TARGET_());
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public payable {
        require(true);
        c.buyShares(to);
        bool isBelowBefore = c._RState_() == 2;
        uint256 baseReserveBefore = uint256(c._BASE_RESERVE_());
        uint256 baseTargetBefore = uint256(c._BASE_TARGET_());
        if (isBelowBefore && baseReserveBefore < baseTargetBefore) {
            c.correctRState();
        }
        uint256 baseTargetAfter = uint256(c._BASE_TARGET_());
        assert(isBelowBefore && baseReserveBefore < baseTargetBefore ? baseTargetAfter <= baseTargetBefore : true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address to,
        uint256 priceLimit,
        uint256 newI
    ) public payable {
        require(true);
        c.buyShares(to);
        c.adjustPriceLimit(priceLimit);
        c.adjustPrice(newI);
        c.correctRState();
        uint256 baseTarget = c._BASE_TARGET_();
        uint256 baseReserve = c._BASE_RESERVE_();
        assert(baseTarget == baseReserve);
    }
}

