// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 baseReserve, uint256 quoteReserve, uint256 baseTarget, uint256 quoteTarget) public {
        // Restrict to the BELOW_ONE state region where the first branch can be entered
        vm.assume(baseReserve > 0 && baseReserve < baseTarget);
        vm.assume(quoteReserve > 0 && quoteReserve < quoteTarget);
        // Bound to avoid overflows later, but keep wide enough to find the bug
        baseReserve = bound(baseReserve, 1, type(uint112).max / 2);
        quoteReserve = bound(quoteReserve, 1, type(uint112).max / 2);
        baseTarget = bound(baseTarget, baseReserve + 1, type(uint112).max);
        quoteTarget = bound(quoteTarget, quoteReserve + 1, type(uint112).max);

        // Use vm.store to set the relevant state variables to the fuzzed values.
        // Storage slot layout (compiled with solc ^0.8.0, assuming default optimizer):
        // GSPStorage layout:
        // slot 0: _status (ReentrancyGuard)
        // slot 1: _GSP_INITIALIZED_ & _IS_OPEN_TWAP_ packed
        // slot 2: _MAINTAINER_
        // slot 3: _BASE_TOKEN_
        // slot 4: _QUOTE_TOKEN_
        // slot 5: _BASE_RESERVE_ (uint112) & _QUOTE_RESERVE_ (uint112) packed
        // slot 6: _BLOCK_TIMESTAMP_LAST_ (uint32) & _BASE_PRICE_CUMULATIVE_LAST_ (uint256) not fully packed? Actually slot 6 and 7.
        // slot 8: _BASE_TARGET_ (uint112) & _QUOTE_TARGET_ (uint112) packed
        // slot 9: _RState_ (uint32) packed
        // slot 10: symbol, but we don't need it.
        // We want to set _BASE_RESERVE_, _QUOTE_RESERVE_, _BASE_TARGET_, _QUOTE_TARGET_, _RState_.
        // slot 5: pack _BASE_RESERVE_ (uint112, lower bits) and _QUOTE_RESERVE_ (uint112, upper bits)
        // slot 8: pack _BASE_TARGET_ (uint112, lower bits) and _QUOTE_TARGET_ (uint112, upper bits)
        // slot 9: _RState_ (uint32) packed with other variables, but we set the whole word to uint32(PMMPricing.RState.BELOW_ONE) = 2.
        vm.store(address(c), bytes32(uint256(5)), bytes32((quoteReserve << 112) | baseReserve));
        vm.store(address(c), bytes32(uint256(8)), bytes32((quoteTarget << 112) | baseTarget));
        vm.store(address(c), bytes32(uint256(9)), bytes32(uint256(2))); // RState.BELOW_ONE

        // Drive the state transition
        c.correctRState();

        // Assert the invariant: after the transition, _BASE_TARGET_ must equal _BASE_RESERVE_
        assertTrue(c._BASE_TARGET_() == c._BASE_RESERVE_());
    }
}

