pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint256 baseReserve,
        uint256 quoteReserve,
        uint256 baseTarget,
        uint256 quoteTarget,
        uint256 i
    ) public {
        // Keep values in admissible ranges (no overflow, valid uint112 etc.)
        vm.assume(baseReserve > 0 && baseReserve < type(uint112).max);
        vm.assume(quoteReserve > 0 && quoteReserve < type(uint112).max);
        vm.assume(baseTarget > 0 && baseTarget < type(uint112).max);
        vm.assume(quoteTarget > 0 && quoteTarget < type(uint112).max);
        vm.assume(i > 0 && i < 1e36);
        // Only relevant when the BELOW_ONE guard fires: BASE_RESERVE_ < BASE_TARGET_
        vm.assume(baseReserve < baseTarget);

        // Deploy minimal token implementations to satisfy the GSPStorage state
        Token baseToken = new Token();
        Token quoteToken = new Token();
        // Use vm.store to set private base/quote token slots (slot positions are derived from the layout).
        // GSPStorage layout:
        // slot 0: _status (ReentrancyGuard)
        // slot 1: _GSP_INITIALIZED_ (bool)
        // slot 2: _IS_OPEN_TWAP_ (bool) + _MAINTAINER_ (address)
        // slot 3: _BASE_TOKEN_ (address)
        // slot 4: _QUOTE_TOKEN_ (address)
        // slot 5: _BASE_RESERVE_ (uint112) + _QUOTE_RESERVE_ (uint112)
        // slot 6: _BLOCK_TIMESTAMP_LAST_ (uint32) + _BASE_PRICE_CUMULATIVE_LAST_ (uint256)
        // slot 7: _BASE_TARGET_ (uint112) + _QUOTE_TARGET_ (uint112)
        // slot 8: _RState_ (uint32) + symbol (string) -> not needed
        // We set the storage directly to put the contract in a BELOW_ONE state with the desired reserves/targets.
        vm.store(address(c), bytes32(uint256(3)), bytes32(uint256(uint160(address(baseToken)))));
        vm.store(address(c), bytes32(uint256(4)), bytes32(uint256(uint160(address(quoteToken)))));
        // _BASE_RESERVE_ and _QUOTE_RESERVE_ packed in slot 5 (uint112: low bits base, high bits quote)
        bytes32 slot5 = bytes32((quoteReserve << 112) | baseReserve);
        vm.store(address(c), bytes32(uint256(5)), slot5);
        // _BASE_TARGET_ and _QUOTE_TARGET_ packed in slot 7
        bytes32 slot7 = bytes32((quoteTarget << 112) | baseTarget);
        vm.store(address(c), bytes32(uint256(7)), slot7);
        // _RState_ is packed at slot 8; we need RState.BELOW_ONE (2)
        vm.store(address(c), bytes32(uint256(8)), bytes32(uint256(2)));
        // _I_ is a separate slot (derived: let's find it). The layout after GSPStorage:
        // slot 11: _MT_FEE_RATE_
        // slot 12: _LP_FEE_RATE_
        // slot 13: _K_
        // slot 14: _I_
        // We can simply use the known slot numbers from GSPStorage.
        // Actually safer: use the public adjustPrice setter? No, need maintainer. Instead compute correct slot for _I_.
        // In GSPStorage, after DOMAIN_SEPARATOR, PERMIT_TYPEHASH, nonces mapping, etc. The easiest is to not touch _I_ 
        // and set it via the public adjustPrice? Requires _MAINTAINER_. We can set _MAINTAINER_ to ourselves and call adjustPrice, or store directly.
        // Set _MAINTAINER_ to address(this) so we can configure i.
        vm.store(address(c), bytes32(uint256(2)), bytes32(uint256(uint160(address(this)))));
        // Now call adjustPrice(i) as maintainer
        c.adjustPrice(i);

        // The reference's correctRState should set _BASE_TARGET_ = _BASE_RESERVE_ after transition.
        // Call correctRState
        c.correctRState();

        // After correctRState, the state should be ONE (RState == uint32(PMMPricing.RState.ONE) which is 1)
        // and _BASE_TARGET_ must equal _BASE_RESERVE_.
        // We get the current RState from the public getter _RState_
        uint256 rState = c._RState_();
        // If the transition happened (RState becomes ONE), assert the invariant that held in the original: _BASE_TARGET_ == _BASE_RESERVE_.
        // The buggy version violates this.
        if (rState == 1) {
            uint256 baseTargetAfter = c._BASE_TARGET_();
            uint256 baseReserveAfter = c._BASE_RESERVE_();
            assertTrue(baseTargetAfter == baseReserveAfter);
        } else {
            // If no transition, test passes vacuously (the invariant only matters on transition).
            assertTrue(true);
        }
    }
}

// Minimal ERC20 mock needed to store addresses in the token slots.
contract Token {
    function balanceOf(address) external pure returns (uint256) { return 0; }
}

